#!/bin/sh
# Kør efter ændringer i assets/site.css, site.js, round*.js, *-tekst.js eller kanon.json: opdaterer ?v= i alle html-filer.
cd "$(dirname "$0")" || exit 1
if command -v md5 >/dev/null 2>&1; then h() { md5 -q "$1"; }; else h() { md5sum "$1" | cut -c1-32; }; fi
v=$(printf '%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s%s' "$(h assets/kanon.json)" "$(h assets/site.css)" "$(h assets/site.js)" "$(h assets/round3.js)" "$(h assets/round4.js)" "$(h assets/round5.js)" "$(h assets/round5-tekst.js)" "$(h assets/round6.js)" "$(h assets/round6-tekst.js)" "$(h assets/ankre.js)" "$(h assets/round9.js)" "$(h assets/round9-tekst.js)" "$(h assets/round10.js)" "$(h assets/forside.css)" "$(h assets/forside.js)" "$(h assets/undersider.css)" "$(h assets/undersider.js)" "$(h assets/arkiv-v1.js)" "$(h assets/infrakort.css)" "$(h assets/infrakort.js)" "$(h assets/kaede.js)" "$(h assets/vagt.css)" "$(h assets/vagt.js)" "$(h assets/maaling.js)" "$(h assets/arkivskab.js)" "$(h assets/doeren.js)" | ( command -v md5 >/dev/null 2>&1 && md5 -q || md5sum | cut -c1-32 ) | cut -c1-8)
for f in $(find . -name index.html -not -path "./node_modules/*" -not -path "./worker/*" -not -path "./byggepakke/*" -not -path "./Tingsvad-*" -not -path "./.wrangler/*" -not -path "./arkivet/protokol/*" -not -path "./en/archive/minutes/*") 404.html; do
  if sed --version >/dev/null 2>&1; then sed -i -E "s#(assets/(site\.css|site\.js|round3\.js|round4\.js|round5\.js|round5-tekst\.js|round6\.js|round6-tekst\.js|ankre\.js|round9\.js|round9-tekst\.js|round10\.js|forside\.css|forside\.js|undersider\.css|undersider\.js|arkiv-v1\.js|infrakort\.css|infrakort\.js|kaede\.js|vagt\.css|vagt\.js|maaling\.js|arkivskab\.js|doeren\.js))(\?v=[0-9a-zA-Z]+)?\"#\1?v=$v\"#g" "$f"; else sed -i '' -E "s#(assets/(site\.css|site\.js|round3\.js|round4\.js|round5\.js|round5-tekst\.js|round6\.js|round6-tekst\.js|ankre\.js|round9\.js|round9-tekst\.js|round10\.js|forside\.css|forside\.js|undersider\.css|undersider\.js|arkiv-v1\.js|infrakort\.css|infrakort\.js|kaede\.js|vagt\.css|vagt\.js|maaling\.js|arkivskab\.js|doeren\.js))(\?v=[0-9a-zA-Z]+)?\"#\1?v=$v\"#g" "$f"; fi
done
d=$(date +%F); if sed --version >/dev/null 2>&1; then sed -i -E "s#<lastmod>[0-9-]+</lastmod>#<lastmod>$d</lastmod>#g" sitemap.xml; else sed -i '' -E "s#<lastmod>[0-9-]+</lastmod>#<lastmod>$d</lastmod>#g" sitemap.xml; fi
echo "v=$v lastmod=$d"
